def minOperations(nums: List[int]) -> int:
    stack = []
    ans = 0
    for v in nums:
        if v == 0:
            stack = []
            continue
        while stack and stack[-1] > v:
            stack.pop()
        if stack and stack[-1] == v:
            continue
        stack.append(v)
        ans += 1
    return ans
